    },
    {
      "claim": "No affirmative query-specific evidence supports F >= 20%; the low prediction remains supported by transferable human low-F outcomes and the query's large, highly ionized, high-TPSA structure.",
      "card_ids": ["C01","C03","C05","C07","C10","C11","C14","C16","C17","C20","C02"]
    }
  ],
  "new_evidence_assessment": [
